from pathlib import Path
import json
import os

ROOT=Path(__file__).resolve().parents[2]
PROGRAM=(ROOT/'docs/BOS/PROGRAMA_ESTRATEGICO_BOS_EDARSAHUB_DIRECCION.md').read_text(encoding='utf-8').lower()

def corpus():
    parts=[]
    for base in (ROOT/'backend',ROOT/'docs/BOS',ROOT/'docs/agent-governance'):
        if not base.exists(): continue
        for p in base.rglob('*'):
            if p.is_file() and p.suffix.lower() in {'.py','.md','.json'} and 'test_bos_v1_gate_e_executive_bos_certification.py' not in str(p):
                try: parts.append(p.read_text(encoding='utf-8',errors='ignore').lower())
                except Exception: pass
    return '\n'.join(parts)

def certified_jobs():
    runtime=Path(str(os.environ.get('EDARSAHUB_ROOT') or '/app'))/'.git/universal-worker-queue/results'
    out=[]
    if runtime.is_dir():
        for p in runtime.glob('*.json'):
            try:
                d=json.loads(p.read_text(encoding='utf-8'))
                if d.get('certification')=='CERTIFIED' and d.get('percent_complete')==100 and not d.get('production_touched',False): out.append(str(d).lower())
            except Exception: pass
    return '\n'.join(out)

def test_gate_e_existing_executive_evidence_complete():
    assert 'gate e - bos ejecutivo' in PROGRAM
    text=corpus()+'\n'+certified_jobs()
    chain=['bos-direccion-status-engine','bos-direccion-evidence-collector','bos-direccion-snapshot-publisher','bos-direccion-recurrent-status','bos-direccion-scheduler-activation','bos-direccion-e2e-informe-ejecutivo-gate7-r3']
    missing_chain=[x for x in chain if x not in text]
    assert not missing_chain, 'GATE_E_STATUS_CHAIN_MISSING:'+','.join(missing_chain)
    requirements={
      'status':['status','estado'],
      'problems':['problema','blocker','riesgo'],
      'causes':['causa','reason','diagnostic'],
      'priorities':['prioridad','atender','attention'],
      'recommendations':['recomend','recommendation'],
      'authorized_actions':['accion autorizada','authorized action','execution gate','ejecutar']
    }
    missing=[]
    for name,tokens in requirements.items():
        if not any(t in text for t in tokens): missing.append(name)
    assert not missing, 'GATE_E_MISSING_EVIDENCE:'+','.join(missing)
